using System;
using System.Data;
using System.Text;
using System.Web.UI;
using System.Web.UI.WebControls;
using BO;
using DataAccess;
using WebGlobal;

namespace InformationWeb.Dashboards.Student
{
    /// <summary>
    /// Bộ lọc Khoa / Khóa / Lớp cho dashboard sĩ số lớp (multi-select).
    /// </summary>
    public partial class UClassFilter : UserControl
    {
        private const string SESSION_CLASS_TABLE = "SCS_DASH_CLASS_TABLE";

        private string GetSelectedValues(ListBox listBox)
        {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < listBox.Items.Count; i++)
            {
                if (listBox.Items[i].Selected)
                {
                    if (sb.Length > 0)
                        sb.Append(",");
                    sb.Append(listBox.Items[i].Value);
                }
            }
            if (sb.Length > 0)
                return sb.ToString();
            return null;
        }

        public string ScienceID
        {
            get { return GetSelectedValues(ddlScienceID); }
        }

        public string CourseID
        {
            get { return GetSelectedValues(ddlCourseID); }
        }

        public string ClassID
        {
            get { return GetSelectedValues(ddlClassID); }
        }

        public string ScienceClientID
        {
            get { return ddlScienceID.ClientID; }
        }

        public string CourseClientID
        {
            get { return ddlCourseID.ClientID; }
        }

        public string ClassClientID
        {
            get { return ddlClassID.ClientID; }
        }

        public void LoadData()
        {
            DataTable dtbScience = new SIM_ScienceDAO().Search();
            ddlScienceID.DataSource = dtbScience;
            ddlScienceID.DataTextField = SIM_Science.C_SCIENCENAME;
            ddlScienceID.DataValueField = SIM_Science.C_SCIENCEID;
            ddlScienceID.DataBind();

            DataTable dtbCourse = new SIM_CourseDAO().Search("@IsActived", 1);
            ddlCourseID.DataSource = dtbCourse;
            ddlCourseID.DataTextField = SIM_Course.C_COURSENAME;
            ddlCourseID.DataValueField = SIM_Course.C_COURSEID;
            ddlCourseID.DataBind();

            DataTable dtbClass = new SIM_ClassDAO().Search("@ClassType", 0, "@IsActived", 1);
            Session[SESSION_CLASS_TABLE] = dtbClass;
            ddlClassID.DataSource = dtbClass;
            ddlClassID.DataTextField = SIM_Class.C_CLASSNAME;
            ddlClassID.DataValueField = SIM_Class.C_CLASSID;
            ddlClassID.DataBind();
        }

        protected void Page_Load(object sender, EventArgs e)
        {
            if (!IsPostBack)
            {
                if (ddlClassID.Items.Count == 0)
                    LoadData();
            }
        }
    }
}

