function isFilterValueActive(val) {
    if (val === null || val === undefined || val === "") {
        return false;
    }
    // Multi-select: if only commas (no real values), treat as inactive
    if (val.replace(/,/g, "").trim() === "") {
        return false;
    }
    return true;
}

