    var el = document.getElementById(clientId);
    var currentValue = preserveValue !== undefined && preserveValue !== null ? String(preserveValue) : "";
    var multipleValues = [];
    if (el && el.multiple) {
        // Lưu tất cả giá trị đang chọn
