function fillFilterDropdown(clientId, rows, valueField, textField) {
    var container = document.getElementById(clientId);
    if (!container) {
        return;
    }
    var menu = container.querySelector(".scs-ms-menu");
    if (!menu) {
        return;
    }
    // Xoá nội dung cũ
    menu.innerHTML = "";
    // "Tất cả"
    var allLabel = document.createElement("label");
    allLabel.className = "scs-ms-item scs-ms-all-item";
    var allCheck = document.createElement("input");
    allCheck.type = "checkbox";
    allCheck.className = "scs-ms-check-all";
    allCheck.checked = true;
    allLabel.appendChild(allCheck);
    allLabel.appendChild(document.createTextNode(" Tất cả"));
    menu.appendChild(allLabel);
    var allDiv = document.createElement("div");
    allDiv.className = "scs-ms-divider";
    menu.appendChild(allDiv);
    // Empty state
    var emptyEl = document.createElement("div");
    emptyEl.className = "scs-ms-empty d-none";
    emptyEl.textContent = "Không có dữ liệu";
    menu.appendChild(emptyEl);
    // Các mục cá nhân
    if (rows && rows.length > 0) {
        var i;
        var row;
        for (i = 0; i < rows.length; i++) {
            row = rows[i];
            var value = row[valueField] !== null && row[valueField] !== undefined ? String(row[valueField]) : "";
            var text = row[textField] !== null && row[textField] !== undefined ? String(row[textField]) : "";
            var label = document.createElement("label");
            label.className = "scs-ms-item";
            var check = document.createElement("input");
            check.type = "checkbox";
            check.className = "scs-ms-check";
            check.value = value;
            check.checked = true;
            label.appendChild(check);
            label.appendChild(document.createTextNode(" " + text));
            menu.appendChild(label);
        }
    } else {
        allLabel.className = "scs-ms-item scs-ms-all-item d-none";
        allDiv.className = "scs-ms-divider d-none";
        emptyEl.className = "scs-ms-empty";
    }
    bindMultiSelectEvents(container);
    updateMultiSelectCount(container);
}

