        return;
    }
    if (!preserveValue || String(preserveValue).trim() === "") {
        // Mặc định chọn tất cả
        var allCb = container.querySelector(".scs-ms-check-all");
        if (allCb) {
            allCb.checked = true;
        }
        updateMultiSelectCount(container);
        return;
    }
    var savedValues = String(preserveValue).split(",");
    // Bỏ chọn tất cả
    var checks = container.querySelectorAll(".scs-ms-check");
    var i;
    var k;
    for (i = 0; i < checks.length; i++) {
        checks[i].checked = false;
    }
    var allCb2 = container.querySelector(".scs-ms-check-all");
    if (allCb2) {
        allCb2.checked = false;
    }
    // Chỉ check những giá trị cần giữ
    for (i = 0; i < checks.length; i++) {
        for (k = 0; k < savedValues.length; k++) {
            if (checks[i].value === savedValues[k]) {
                checks[i].checked = true;
                break;
            }
        }
    }
    updateMultiSelectCount(container);
}

